-- One-time Hecate hosted cleanup, 2026-09-21. Run against project
-- myqsbtpfertaltyzaoyk after verifying the legacy table is empty.
-- The transaction preserves each account's earliest and latest discovery dates.
begin;
lock table public.discovered_cities in share row exclusive mode;
lock table public.discovery_points in access exclusive mode;
do $$
begin
  if exists (select 1 from public.discovery_points) then
    raise exception 'discovery_points is no longer empty; inspect and migrate its rows before dropping it';
  end if;
end;
$$;

create or replace function public.preserve_discovered_city_first_seen()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.first_discovered_at := least(old.first_discovered_at, new.first_discovered_at,
    old.last_discovered_at, new.last_discovered_at);
  new.last_discovered_at := greatest(old.last_discovered_at, new.last_discovered_at);
  return new;
end;
$$;

