from public.discovered_cities
where city_id in ('relation:51781', 'relation:183779', 'region:greater-london')
group by user_id
on conflict (user_id, city_id) do update set
  name = excluded.name,
  geometry = excluded.geometry,
  first_discovered_at = excluded.first_discovered_at,
  last_discovered_at = excluded.last_discovered_at;

delete from public.discovered_cities
where city_id in ('relation:51781', 'relation:183779');

