  min(least(first_discovered_at, last_discovered_at)),
  max(greatest(first_discovered_at, last_discovered_at))
from public.discovered_cities
where city_id in ('relation:8398124', 'region:new-york')
group by user_id
on conflict (user_id, city_id) do update set
  name = excluded.name,
  geometry = excluded.geometry,
  first_discovered_at = excluded.first_discovered_at,
  last_discovered_at = excluded.last_discovered_at;

delete from public.discovered_cities
where city_id = 'relation:8398124';

-- Repair a previously inverted first/last pair caused by the old upsert trigger.
update public.discovered_cities
set first_discovered_at = least(first_discovered_at, last_discovered_at),
    last_discovered_at = greatest(first_discovered_at, last_discovered_at)
where first_discovered_at > last_discovered_at;

-- Stop older deployed clients from reintroducing these obsolete city IDs.
alter table public.discovered_cities
  add constraint discovered_cities_no_obsolete_region_ids
  check (city_id not in (
    'relation:347950', 'relation:345761',
    'relation:51781', 'relation:183779', 'relation:8398124'
  ));

drop table public.discovery_points;
commit;
